import json
from rapidfuzz import fuzz, process

# Define a dictionary to map abbreviations to their full forms
abbreviation_map = {
    'hn': 'hijo natural',
    'hl': 'hijo legitimo',
    'id': 'indigena',
    'indo': 'indio'
}

# Define a dictionary to map ethno-racial categories, legitimacy status, and geographic locations to their canonical forms
canonical_facet_map = {
    'ethno_racial_category': {
        'indio': ['indio', 'indigina', 'indigena', 'indijena', 'indijino'],
        'espanol': ['espanol', 'espanola'],
        'mestiza': ['mestiza']
    },
    'legitimacy_status': {
        'legitimo': ['legitimo', 'legitima'],
        'natural': ['natural'],
        'espurio': ['espurio', 'espuria']
    },
    'geographic_location': {
        'aucara': ['aucara'],
        'pampamarca': ['pampamarca'],
        'chacralla': ['chacralla'],
        'ishua': ['ishua'],
        'punas': ['punas']
    }
}

def normalize_term(term):
    # Map abbreviations to their full forms
    if term in abbreviation_map:
        return abbreviation_map[term]

    # Use fuzzy matching to normalize terms with scribal errors
    for facet, canonical_terms in canonical_facet_map.items():
        for canonical_term, variants in canonical_terms.items():
            if term in variants:
                return canonical_term
            else:
                best_match = process.extractOne(term, variants, scorer=fuzz.ratio)
                if best_match and best_match[1] > 80:  # Adjust the threshold as needed
                    return canonical_term

    return term

def classify_term(term):
    for facet, canonical_terms in canonical_facet_map.items():
        for canonical_term, variants in canonical_terms.items():
            if term == canonical_term or term in variants:
                return facet
    return 'unknown'

def parse_clusters(log_output):
    clusters = log_output.strip().split('\n')
    normalized_clusters = []

    for cluster in clusters:
        cluster_id = cluster.split(':')[0].strip()
        terms = cluster.split(':')[1].strip().split(',')
        normalized_terms = []

        for term in terms:
            normalized_term = normalize_term(term.strip())
            facet = classify_term(normalized_term)
            normalized_terms.append({
                'term': normalized_term,
                'facet': facet
            })

        normalized_clusters.append({
            'cluster_id': cluster_id,
            'terms': normalized_terms
        })

    return normalized_clusters

log_output = '''Cluster 0: hijos,indigino,indigina,punas,natural,hijo natural,tributario,indio aucara,indio,espanol,legitimo,hijo legitimo,hijo,aucara,aucara hijo
